BEGIN;
CREATE SCHEMA maintenance_registration_private;REVOKE ALL ON SCHEMA maintenance_registration_private FROM PUBLIC;GRANT USAGE ON SCHEMA maintenance_registration_private TO anon,authenticated,service_role;
ALTER TABLE public.maintenance_partners ADD COLUMN onboarding_profile jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(onboarding_profile)='object');
CREATE TABLE maintenance_private.partner_invites(company_id uuid PRIMARY KEY REFERENCES public.companies(id),token text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL DEFAULT now()+interval '180 days',created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE maintenance_private.partner_invites ENABLE ROW LEVEL SECURITY;REVOKE ALL ON maintenance_private.partner_invites FROM PUBLIC,anon,authenticated;CREATE POLICY invite_owner ON maintenance_private.partner_invites TO authenticated USING(maintenance_private.partner_access(company_id,true));
CREATE INDEX partner_invite_creator ON maintenance_private.partner_invites(created_by);
CREATE TABLE public.maintenance_partner_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),request_id uuid NOT NULL,protocol text GENERATED ALWAYS AS ('OFI-'||upper(substr(replace(id::text,'-',''),1,12))) STORED,cnpj text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovada','recusada')),submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(),consent_version text NOT NULL DEFAULT '2026-10-23-v1',reviewed_at timestamptz,reviewed_by uuid REFERENCES auth.users(id),review_note text,partner_id uuid,UNIQUE(company_id,request_id),UNIQUE(id,company_id),FOREIGN KEY(partner_id,company_id) REFERENCES public.maintenance_partners(id,company_id));
CREATE UNIQUE INDEX request_open_cnpj ON public.maintenance_partner_requests(company_id,cnpj) WHERE status IN ('pendente','aprovada');
CREATE INDEX request_company_date ON public.maintenance_partner_requests(company_id,status,submitted_at DESC);CREATE INDEX request_reviewer ON public.maintenance_partner_requests(reviewed_by);CREATE INDEX request_partner ON public.maintenance_partner_requests(company_id,partner_id);
CREATE TABLE public.maintenance_partner_request_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),request_id uuid NOT NULL,actor_id uuid REFERENCES auth.users(id),action text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),note text,FOREIGN KEY(request_id,company_id) REFERENCES public.maintenance_partner_requests(id,company_id));
CREATE INDEX request_audit_entity ON public.maintenance_partner_request_audit(company_id,request_id);CREATE INDEX request_audit_actor ON public.maintenance_partner_request_audit(actor_id);
ALTER TABLE public.maintenance_partner_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE public.maintenance_partner_request_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.maintenance_partner_requests,public.maintenance_partner_request_audit FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.maintenance_partner_requests,public.maintenance_partner_request_audit TO authenticated;GRANT ALL ON public.maintenance_partner_requests,public.maintenance_partner_request_audit TO service_role;
CREATE POLICY requests_read ON public.maintenance_partner_requests FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id));CREATE POLICY request_audit_read ON public.maintenance_partner_request_audit FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id));
CREATE FUNCTION maintenance_private.registration_cnpj(doc text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$ DECLARE n integer;idx integer;total integer;digit integer;weights integer[];BEGIN
 IF doc !~ '^[A-Z0-9]{12}[0-9]{2}$' OR doc ~ '^(.)\1{13}$' THEN RETURN false;END IF;
 FOR n IN 12..13 LOOP weights:=CASE WHEN n=12 THEN ARRAY[5,4,3,2,9,8,7,6,5,4,3,2] ELSE ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2] END;total:=0;FOR idx IN 1..n LOOP total:=total+(ascii(substr(doc,idx,1))-48)*weights[idx];END LOOP;digit:=total%11;digit:=CASE WHEN digit<2 THEN 0 ELSE 11-digit END;IF substr(doc,n+1,1)::integer<>digit THEN RETURN false;END IF;END LOOP;RETURN true;END $$;
CREATE FUNCTION maintenance_private.registration_profile(profile jsonb,required boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE schema_data jsonb:=$fields$[["inscricao_estadual","Inscrição estadual"],["inscricao_municipal","Inscrição municipal"],["cnae","CNAE principal"],["regime_tributario","Regime tributário","select",["Não informado","Simples Nacional","Lucro Presumido","Lucro Real","MEI","Outro"]],["ano_fundacao","Ano de fundação","number",1900,2100],["site","Site"],["responsavel_legal","Responsável legal"],["cargo_responsavel","Cargo do responsável"],["rede_concessionaria","Rede / concessionária / grupo"],["comercial_nome","Contato comercial"],["comercial_telefone","Telefone comercial","tel"],["comercial_email","E-mail comercial","email"],["operacao_nome","Responsável pela operação"],["operacao_telefone","Telefone da operação","tel"],["operacao_email","E-mail da operação","email"],["financeiro_nome","Contato financeiro"],["financeiro_telefone","Telefone financeiro","tel"],["financeiro_email","E-mail financeiro","email"],["emergencia_nome","Contato de emergência"],["emergencia_telefone","Telefone de emergência","tel"],["canal_orcamento","Canal preferido para orçamento","select",["WhatsApp","E-mail","Telefone","Portal"]],["canal_andamento","Canal para acompanhamento","select",["WhatsApp","E-mail","Telefone","Portal"]],["marcas","Marcas atendidas","multi",["Agrale","Audi","BMW","BYD","CAOA Chery","Chevrolet","Citroën","DAF","Fiat","Ford","Honda","Hyundai","Iveco","JAC","Jeep","Kia","Land Rover","MAN","Mercedes-Benz","Mitsubishi","Nissan","Peugeot","RAM","Renault","Scania","Shacman","Toyota","Volkswagen","Volvo"]],["servicos","Serviços prestados","multi",["Mecânica geral","Motor","Câmbio manual","Câmbio automático","Embreagem","Freios","Suspensão","Direção","Elétrica","Eletrônica / diagnóstico","Injeção diesel","Injeção eletrônica","Ar-condicionado","Arrefecimento","Troca de óleo e filtros","Pneus e borracharia","Alinhamento e balanceamento","Funilaria e pintura","Solda e caldeiraria","Implementos e carretas","Hidráulica / pneumática","Tacógrafo","Rastreamento","Inspeção veicular","Socorro / guincho","Lavagem / higienização"]],["modalidades","Tipos de atendimento","multi",["Preventiva","Corretiva","Preditiva","Diagnóstico","Revisão","Inspeção","Emergencial","Garantia"]],["combustiveis","Motorização / combustível","multi",["Diesel","Gasolina","Etanol","Flex","GNV","Elétrico","Híbrido"]],["restricoes_veiculos","Restrições de marcas / modelos / veículos","textarea"],["modelos_especificos","Modelos e linhas com especialização","textarea"],["servicos_terceirizados","Serviços terceirizados e parceiros","textarea"],["regiao_atendida","Cidades / região atendida","textarea"],["raio_atendimento_km","Raio de atendimento (km)","number",0,10000],["atendimento_externo","Atendimento externo / móvel","bool"],["retira_entrega","Retira e entrega veículo","bool"],["estacionamento_seguro","Pátio / estacionamento seguro","bool"],["equipamentos","Equipamentos disponíveis","multi",["Scanner multimarcas","Scanner diesel","Elevador leve","Elevador pesado","Rampa de alinhamento","Valeta","Balança","Bancada de injeção","Socorro móvel","Guincho leve","Guincho pesado"]],["boxes","Número de boxes","number",0,500],["capacidade_dia","Capacidade de veículos por dia","number",0,1000],["equipe_tecnica","Número de técnicos","number",0,1000],["altura_max_m","Altura máxima atendida (m)","number",0,20],["peso_max_t","Peso máximo atendido (t)","number",0,500],["certificacoes","Certificações e qualificações (descrição)","textarea"],["garantia_dias","Garantia dos serviços (dias)","number",0,3650],["garantia_condicoes","Condições / cobertura de garantia","textarea"],["prazo_orcamento_h","Prazo estimado para orçamento (horas)","number",0,8760],["prazo_resposta_h","Prazo estimado de resposta (horas)","number",0,8760],["pecas","Política de peças","multi",["Originais","Genuínas","Paralelas homologadas","Remanufaturadas","Peças fornecidas pelo cliente"]],["restricoes_acesso","Referência / acesso para veículos pesados","textarea"],["aceita_faturado","Aceita pagamento faturado","select",["Sim","Não","Sujeito à análise"]],["formas_pagamento","Formas de pagamento","multi",["Boleto faturado","PIX","Transferência","Cartão de crédito","Cartão de débito","Dinheiro"]],["prazos_faturado","Prazos de faturamento disponíveis","multi",["7 dias","10 dias","14 dias","15 dias","21 dias","28 dias","30 dias","45 dias","60 dias","90 dias"]],["dia_faturamento","Dia / regra de fechamento do faturamento"],["limite_faturado","Limite de crédito sujeito a cadastro (R$)","number",0,100000000],["emite_nf","Emite nota fiscal","select",["Sim","Não"]],["nf_servico_pecas","Nota fiscal de serviços e peças","select",["Separadas","Conjugada","Somente serviços","Somente peças"]],["exige_os","Exige OS / pedido de compra para faturar","bool"],["exige_aprovacao","Só executa após aprovação formal","bool"],["exigencias_cadastro","Documentos / requisitos para liberar faturamento (descrever)","textarea"],["condicoes_comerciais","Regras de cobrança, parcelamento e condições adicionais","textarea"],["taxa_deslocamento","Taxa / condições de deslocamento e socorro","textarea"],["diferenciais","Diferenciais da oficina","textarea"],["observacoes","Observações e informações adicionais","textarea"]]$fields$::jsonb;field jsonb;k text;v jsonb;typ text;opts jsonb;n numeric;BEGIN
 IF profile IS NULL OR jsonb_typeof(profile)<>'object' OR octet_length(profile::text)>60000 THEN RAISE EXCEPTION 'Perfil cadastral inválido.';END IF;
 FOR k IN SELECT jsonb_object_keys(profile) LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(schema_data) f WHERE f->>0=k) THEN RAISE EXCEPTION 'Campo de perfil não permitido: %',k;END IF;END LOOP;
 FOR field IN SELECT value FROM jsonb_array_elements(schema_data) LOOP k:=field->>0;typ:=coalesce(field->>2,'text');v:=profile->k;
 IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
 IF typ='multi' THEN IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>60 THEN RAISE EXCEPTION 'Lista inválida: %',k;END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION 'Opção inválida: %',k;END IF;
 ELSIF typ='number' THEN IF v#>>'{}' !~ '^[0-9]+([.][0-9]{1,2})?$' THEN RAISE EXCEPTION 'Número inválido: %',k;END IF;n:=(v#>>'{}')::numeric;IF k=ANY(ARRAY['ano_fundacao','boxes','capacidade_dia','equipe_tecnica','garantia_dias']) AND n<>trunc(n) THEN RAISE EXCEPTION 'Informe um número inteiro: %',k;END IF;IF n<(field->>3)::numeric OR n>(field->>4)::numeric THEN RAISE EXCEPTION 'Número fora do limite: %',k;END IF;
 ELSIF typ='bool' THEN IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'Opção inválida: %',k;END IF;
 ELSE IF jsonb_typeof(v)<>'string' OR length(v#>>'{}')>(CASE WHEN typ='textarea' THEN 4000 ELSE 200 END) THEN RAISE EXCEPTION 'Texto inválido: %',k;END IF;
 IF typ='select' AND NOT (field->3) ? (v#>>'{}') THEN RAISE EXCEPTION 'Seleção inválida: %',k;END IF;
 IF typ='email' AND v#>>'{}' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN RAISE EXCEPTION 'E-mail inválido: %',k;END IF;
 IF typ='tel' AND regexp_replace(v#>>'{}','[^0-9]','','g') !~ '^(55)?[1-9][0-9][2-9][0-9]{7,8}$' THEN RAISE EXCEPTION 'Telefone inválido: %',k;END IF;
 END IF;END LOOP;
 IF required THEN FOR k IN SELECT unnest(ARRAY['marcas','servicos','modalidades','formas_pagamento']) LOOP IF coalesce(jsonb_array_length(profile->k),0)=0 THEN RAISE EXCEPTION 'Selecione opções em %.',k;END IF;END LOOP;FOR k IN SELECT unnest(ARRAY['aceita_faturado','emite_nf','responsavel_legal']) LOOP IF nullif(btrim(profile->>k),'') IS NULL THEN RAISE EXCEPTION 'Preencha %.',k;END IF;END LOOP;END IF;RETURN profile;END $$;
CREATE FUNCTION maintenance_private.registration_base(b jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$ DECLARE k text;v jsonb;r public.maintenance_partners;doc text;day text;h jsonb;BEGIN
 IF jsonb_typeof(b)<>'object' OR octet_length(b::text)>25000 THEN RAISE EXCEPTION 'Dados gerais inválidos.';END IF;
 FOR k IN SELECT jsonb_object_keys(b) LOOP IF NOT k=ANY(ARRAY['razao_social','nome_fantasia','cnpj_cpf','tipo','especialidades','tipos_veiculo_atendidos','contato_nome','telefone','whatsapp','email','cep','logradouro','numero','complemento','bairro','cidade','estado','pais','latitude','longitude','horario_funcionamento','atende_24h','possui_guincho','valor_hora_mao_obra','prazo_pagamento_dias','desconto_percentual']) THEN RAISE EXCEPTION 'Campo não permitido: %',k;END IF;END LOOP;
 FOR k IN SELECT unnest(ARRAY['razao_social','cnpj_cpf','contato_nome','telefone','email','cep','logradouro','numero','bairro','cidade','estado']) LOOP IF nullif(btrim(b->>k),'') IS NULL THEN RAISE EXCEPTION 'Preencha %.',k;END IF;END LOOP;
 FOR k,v IN SELECT key,value FROM jsonb_each(b) LOOP IF k=ANY(ARRAY['especialidades','tipos_veiculo_atendidos']) THEN IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>60 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION 'Lista inválida: %',k;END IF;
 ELSIF k NOT IN ('horario_funcionamento','atende_24h','possui_guincho','latitude','longitude','valor_hora_mao_obra','prazo_pagamento_dias','desconto_percentual') AND v<>'null'::jsonb AND (jsonb_typeof(v)<>'string' OR length(v#>>'{}')>200) THEN RAISE EXCEPTION 'Texto inválido: %',k;END IF;END LOOP;
 doc:=upper(regexp_replace(b->>'cnpj_cpf','[^A-Za-z0-9]','','g'));IF NOT maintenance_private.registration_cnpj(doc) THEN RAISE EXCEPTION 'CNPJ inválido.';END IF;
 b:=b||jsonb_build_object('cnpj_cpf',doc,'telefone',regexp_replace(b->>'telefone','[^0-9]','','g'),'whatsapp',nullif(regexp_replace(b->>'whatsapp','[^0-9]','','g'),''),'cep',regexp_replace(b->>'cep','[^0-9]','','g'),'pais','BR');
 IF b->>'telefone' !~ '^(55)?[1-9][0-9][2-9][0-9]{7,8}$' OR (b->>'whatsapp' IS NOT NULL AND b->>'whatsapp' !~ '^(55)?[1-9][0-9][2-9][0-9]{7,8}$') THEN RAISE EXCEPTION 'Telefone inválido.';END IF;
 IF b->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' OR b->>'cep' !~ '^[0-9]{8}$' OR b->>'estado' !~ '^(AC|AL|AP|AM|BA|CE|DF|ES|GO|MA|MT|MS|MG|PA|PB|PR|PE|PI|RJ|RN|RS|RO|RR|SC|SP|SE|TO)$' THEN RAISE EXCEPTION 'Revise e-mail, CEP e UF.';END IF;
 IF coalesce(jsonb_array_length(b->'tipos_veiculo_atendidos'),0)=0 THEN RAISE EXCEPTION 'Informe os veículos atendidos.';END IF;
 r:=jsonb_populate_record(NULL::public.maintenance_partners,b);
 IF (r.latitude IS NULL)<>(r.longitude IS NULL) OR r.latitude NOT BETWEEN -90 AND 90 OR r.longitude NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Coordenadas inválidas.';END IF;
 IF r.valor_hora_mao_obra IS NULL OR r.valor_hora_mao_obra NOT BETWEEN 0 AND 10000000000 OR r.desconto_percentual IS NULL OR r.desconto_percentual NOT BETWEEN 0 AND 100 OR r.prazo_pagamento_dias IS NULL OR r.prazo_pagamento_dias NOT BETWEEN 0 AND 3650 THEN RAISE EXCEPTION 'Condições comerciais inválidas.';END IF;
 IF jsonb_typeof(b->'atende_24h') IS DISTINCT FROM 'boolean' OR jsonb_typeof(b->'possui_guincho') IS DISTINCT FROM 'boolean' OR jsonb_typeof(r.horario_funcionamento) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Horários inválidos.';END IF;
 FOR day,h IN SELECT key,value FROM jsonb_each(r.horario_funcionamento) LOOP
 IF NOT day=ANY(ARRAY['seg','ter','qua','qui','sex','sab','dom']) OR jsonb_typeof(h)<>'object' OR jsonb_typeof(h->'aberto') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Horário inválido.';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(h) hk WHERE hk NOT IN ('aberto','inicio','fim')) OR coalesce(h->>'inicio','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' OR coalesce(h->>'fim','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'Horário inválido.';END IF;
 IF NOT r.atende_24h AND (h->>'aberto')::boolean AND h->>'inicio'>=h->>'fim' THEN RAISE EXCEPTION 'Revise abertura e fechamento.';END IF;
 END LOOP;RETURN b;END $$;
CREATE FUNCTION maintenance_private.partner_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$ BEGIN PERFORM maintenance_private.registration_profile(NEW.onboarding_profile);RETURN NEW;END $$;
CREATE TRIGGER partner_profile_guard BEFORE INSERT OR UPDATE OF onboarding_profile ON public.maintenance_partners FOR EACH ROW EXECUTE FUNCTION maintenance_private.partner_profile_guard();
CREATE FUNCTION maintenance_registration_private.external_registration(invite text,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE link maintenance_private.partner_invites;co public.companies;existing public.maintenance_partner_requests;data_base jsonb;profile jsonb;rid uuid;req public.maintenance_partner_requests;BEGIN
 IF invite IS NULL OR length(invite)<>64 THEN RAISE EXCEPTION 'Link indisponível. Solicite um link válido à empresa.';END IF;
 SELECT * INTO link FROM maintenance_private.partner_invites WHERE token=invite AND active AND expires_at>clock_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Link indisponível ou expirado. Solicite um novo link à empresa.';END IF;
 SELECT * INTO co FROM public.companies WHERE id=link.company_id AND ativo FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Cadastro indisponível.';END IF;
 IF action='info' THEN RETURN jsonb_build_object('company',co.nome,'expires_at',link.expires_at,'consent_version','2026-10-23-v1');END IF;
 IF action IS DISTINCT FROM 'submit' OR octet_length(b::text)>90000 OR jsonb_typeof(b)<>'object' THEN RAISE EXCEPTION 'Solicitação inválida.';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(b) k WHERE k NOT IN ('base','profile','consent','declaration','request_id','website_check')) OR coalesce(b->>'website_check','')<>'' THEN RAISE EXCEPTION 'Solicitação inválida.';END IF;
 IF b->'consent' IS DISTINCT FROM 'true'::jsonb OR b->'declaration' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Confirme a declaração e autorização de análise.';END IF;
 rid:=(b->>'request_id')::uuid;IF rid IS NULL THEN RAISE EXCEPTION 'Identificador de envio obrigatório.';END IF;
 data_base:=maintenance_private.registration_base(b->'base');profile:=maintenance_private.registration_profile(b->'profile',true);
 IF profile->>'aceita_faturado'='Sim' AND (data_base->>'prazo_pagamento_dias')::integer<=0 THEN RAISE EXCEPTION 'Informe o prazo para pagamento faturado.';END IF;
 SELECT * INTO existing FROM public.maintenance_partner_requests WHERE company_id=co.id AND request_id=rid;
 IF FOUND THEN IF existing.payload<>jsonb_build_object('base',data_base,'profile',profile) THEN RAISE EXCEPTION 'Envio já registrado com outros dados. Atualize a página para novo cadastro.';END IF;RETURN jsonb_build_object('protocol',existing.protocol,'status','recebida');END IF;
 IF (SELECT count(*) FROM public.maintenance_partner_requests WHERE company_id=co.id AND submitted_at>clock_timestamp()-interval '1 hour')>=30 THEN RAISE EXCEPTION 'Limite temporário de inscrições. Tente mais tarde ou contate a empresa.';END IF;
 IF EXISTS(SELECT 1 FROM public.maintenance_partners WHERE company_id=co.id AND upper(regexp_replace(cnpj_cpf,'[^A-Za-z0-9]','','g'))=data_base->>'cnpj_cpf') OR EXISTS(SELECT 1 FROM public.maintenance_partner_requests WHERE company_id=co.id AND cnpj=data_base->>'cnpj_cpf' AND status IN ('pendente','aprovada')) THEN RAISE EXCEPTION 'Já existe cadastro ou solicitação para este CNPJ. Contate o analista.';END IF;
 INSERT INTO public.maintenance_partner_requests(company_id,request_id,cnpj,payload) VALUES(co.id,rid,data_base->>'cnpj_cpf',jsonb_build_object('base',data_base,'profile',profile)) RETURNING * INTO req;
 INSERT INTO public.maintenance_partner_request_audit(company_id,request_id,action,note) VALUES(co.id,req.id,'enviada','Solicitação externa recebida; sem arquivos.');RETURN jsonb_build_object('protocol',req.protocol,'status','recebida');END $$;
CREATE FUNCTION public.maintenance_partner_registration(invite text,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_registration_private.external_registration(invite,command,body);$$;
CREATE FUNCTION maintenance_private.registration_manage(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid();link maintenance_private.partner_invites;req public.maintenance_partner_requests;rec public.maintenance_partners;partner uuid;page_number integer:=coalesce((b->>'page')::integer,1);page_size integer:=coalesce((b->>'size')::integer,20);status_filter text:=coalesce(b->>'status','pendente');note text:=btrim(coalesce(b->>'note',''));BEGIN
 IF action IS NULL OR action NOT IN ('link','rotate','revoke','list','detail','approve','reject') THEN RAISE EXCEPTION 'Ação inválida.';END IF;
 IF actor IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Sem acesso à empresa.' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.company_members WHERE company_id=c AND user_id=actor AND ativo FOR SHARE;PERFORM 1 FROM public.companies WHERE id=c AND ativo FOR SHARE;IF NOT FOUND OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso revogado.' USING ERRCODE='42501';END IF;
 IF action IN ('link','rotate','revoke','approve','reject') AND NOT maintenance_private.partner_access(c,true) THEN RAISE EXCEPTION 'Somente Admin/Analista gerenciam inscrições.' USING ERRCODE='42501';END IF;
 IF action IN ('link','rotate','revoke') THEN
 IF action='rotate' THEN INSERT INTO maintenance_private.partner_invites(company_id,token,created_by) VALUES(c,replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),actor) ON CONFLICT(company_id) DO UPDATE SET token=excluded.token,active=true,expires_at=clock_timestamp()+interval '180 days',created_at=clock_timestamp(),created_by=actor;
 ELSIF action='revoke' THEN UPDATE maintenance_private.partner_invites SET active=false WHERE company_id=c;END IF;
 SELECT * INTO link FROM maintenance_private.partner_invites WHERE company_id=c;RETURN CASE WHEN link.company_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('token',link.token,'active',link.active,'expires_at',link.expires_at) END;END IF;
 IF action='list' THEN IF status_filter NOT IN ('pendente','aprovada','recusada','todas') OR page_number NOT BETWEEN 1 AND 1000000 OR page_size NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Filtro inválido.';END IF;RETURN jsonb_build_object('pending',(SELECT count(*) FROM public.maintenance_partner_requests WHERE company_id=c AND status='pendente'),'count',(SELECT count(*) FROM public.maintenance_partner_requests WHERE company_id=c AND (status_filter='todas' OR status=status_filter)),'rows',coalesce((SELECT jsonb_agg(to_jsonb(row_req)) FROM (SELECT * FROM public.maintenance_partner_requests WHERE company_id=c AND (status_filter='todas' OR status=status_filter) ORDER BY submitted_at DESC,id OFFSET (page_number-1)*page_size LIMIT page_size) row_req),'[]'::jsonb));END IF;
 SELECT * INTO req FROM public.maintenance_partner_requests WHERE company_id=c AND id=(b->>'id')::uuid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação não encontrada nesta empresa.' USING ERRCODE='42501';END IF;
 IF action='detail' THEN RETURN jsonb_build_object('request',to_jsonb(req),'audit',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.occurred_at) FROM public.maintenance_partner_request_audit a WHERE a.company_id=c AND a.request_id=req.id),'[]'::jsonb));END IF;
 IF action NOT IN ('approve','reject') THEN RAISE EXCEPTION 'Ação inválida.';END IF;
 IF req.status<>'pendente' THEN RAISE EXCEPTION 'Esta solicitação já foi analisada. Atualize a lista.' USING ERRCODE='40001';END IF;
 IF length(note)>4000 OR (action='reject' AND length(note)<3) THEN RAISE EXCEPTION 'Informe um motivo válido para a recusa (até 4000 caracteres).';END IF;
 IF action='approve' THEN PERFORM maintenance_private.registration_profile(req.payload->'profile',true);rec:=jsonb_populate_record(NULL::public.maintenance_partners,maintenance_private.registration_base(req.payload->'base'));
 INSERT INTO public.maintenance_partners(company_id,created_by,razao_social,nome_fantasia,cnpj_cpf,tipo,especialidades,tipos_veiculo_atendidos,contato_nome,telefone,whatsapp,email,cep,logradouro,numero,complemento,bairro,cidade,estado,pais,latitude,longitude,horario_funcionamento,atende_24h,possui_guincho,valor_hora_mao_obra,prazo_pagamento_dias,desconto_percentual,onboarding_profile,status) VALUES(c,actor,rec.razao_social,rec.nome_fantasia,rec.cnpj_cpf,rec.tipo,rec.especialidades,rec.tipos_veiculo_atendidos,rec.contato_nome,rec.telefone,rec.whatsapp,rec.email,rec.cep,rec.logradouro,rec.numero,rec.complemento,rec.bairro,rec.cidade,rec.estado,rec.pais,rec.latitude,rec.longitude,rec.horario_funcionamento,rec.atende_24h,rec.possui_guincho,rec.valor_hora_mao_obra,rec.prazo_pagamento_dias,rec.desconto_percentual,req.payload->'profile','ativo') RETURNING id INTO partner;END IF;
 UPDATE public.maintenance_partner_requests SET status=CASE WHEN action='approve' THEN 'aprovada' ELSE 'recusada' END,reviewed_at=clock_timestamp(),reviewed_by=actor,review_note=note,partner_id=partner WHERE id=req.id RETURNING * INTO req;
 INSERT INTO public.maintenance_partner_request_audit(company_id,request_id,actor_id,action,note) VALUES(c,req.id,actor,req.status,note);RETURN to_jsonb(req);END $$;
CREATE FUNCTION public.maintenance_partner_requests_command(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT maintenance_private.registration_manage(target_company,command,body);$$;
REVOKE ALL ON FUNCTION maintenance_private.registration_cnpj(text),maintenance_private.registration_profile(jsonb,boolean),maintenance_private.registration_base(jsonb),maintenance_private.partner_profile_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION maintenance_private.registration_profile(jsonb,boolean) TO authenticated;
REVOKE ALL ON FUNCTION maintenance_registration_private.external_registration(text,text,jsonb),public.maintenance_partner_registration(text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION maintenance_registration_private.external_registration(text,text,jsonb),public.maintenance_partner_registration(text,text,jsonb) TO anon,authenticated;
REVOKE ALL ON FUNCTION maintenance_private.registration_manage(uuid,text,jsonb),public.maintenance_partner_requests_command(uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION maintenance_private.registration_manage(uuid,text,jsonb),public.maintenance_partner_requests_command(uuid,text,jsonb) TO authenticated;
COMMIT;
